function itemCount(id){return state.inventory.find(i=>i.id===id)?.count||0}
function consume(id,n=1){const it=state.inventory.find(i=>i.id===id);if(!it||it.count<n)return false;it.count-=n;if(it.count<=0)state.inventory.splice(state.inventory.indexOf(it),1);renderInventory();return true}
function setMeter(id,value){state[id]=clamp(value,0,100)}
function toggleOverlay(id){const on=!$(id).classList.contains('open');for(const other of ['#inventoryOverlay','#mapOverlay','#settingsOverlay'])$(other).classList.remove('open');$(id).classList.toggle('open',on);inventoryOpen=on;if(on)document.exitPointerLock?.();else if(started&&!mobile)canvas.requestPointerLock?.();if(id==='#mapOverlay'&&on)drawMap()}
function nearestThing(max=3.4){let best=null,dist=max;const fx=-Math.sin(player.yaw),fz=-Math.cos(player.yaw);for(const p of pickups){if(p.taken)continue;const dx=p.x-player.x,dz=p.z-player.z,d=Math.hypot(dx,dz);if(d>dist)continue;const dot=(dx*fx+dz*fz)/(d||1);if(dot>.1){best={...p,distance:d,entity:p};dist=d}}for(const w of wildlife){if(w.kind!=='deer'||w.dead)continue;const dx=w.x-player.x,dz=w.z-player.z,d=Math.hypot(dx,dz);if(d>dist)continue;const dot=(dx*fx+dz*fz)/(d||1);if(dot>.15){best={type:'wildlife',label:'TRACK WILDLIFE',distance:d,entity:w};dist=d}}if(Math.hypot(player.x,player.z+12)<6&&dist>2.7)best={type:'shelter',label:'REST AT RANGER CABIN',distance:2.8};return best}
function collect(p){if(!p||p.taken)return;if(p.type==='crate'){p.taken=true;p.group.visible=false;addItem('ammo','.22 cartridges','▤','AMMUNITION',8,.3,'DRY','Small-bore cartridges for the worn field rifle.');addItem('bandage','Cloth bandage','✚','MEDICAL SUPPLY',1,.2,'CLEAN','A strip of clean linen. Use it to stop a wound.');addItem('water','Sealed water','◉','DRINKING WATER',1,.8,'SEALED','A clean bottle from a ranger cache.');toast('Cache searched · useful supplies recovered')}else if(p.type==='berries'){p.taken=true;p.group.visible=false;addItem('berries','Wild berries','✣','FIELD PROVISIONS',3,.2,'GOOD','Tart forest berries that restore nourishment.');toast('Wild berries gathered')}else if(p.type==='wood'){p.taken=true;p.group.visible=false;addItem('wood','Dry branches','⌁','FIREWOOD',2,.6,'DRY','Deadfall gathered beneath the firs.');toast('Dry branches gathered')}else if(p.type==='water'){p.taken=true;p.group.visible=false;addItem('water','Sealed water','◉','DRINKING WATER',1,.8,'SEALED','A clean bottle of drinking water.');toast('Water collected')}state.found=pickups.filter(a=>a.taken).map(a=>`${a.type}:${a.x}:${a.z}`);save();renderInventory()}
function interact(){const target=nearestThing();if(!target)return;if(target.type==='wildlife'){toast('The deer slips away into the trees');target.entity.state='flee';target.entity.targetX=player.x+Math.sign(target.entity.x-player.x)*18;target.entity.targetZ=player.z+Math.sign(target.entity.z-player.z)*18;return}if(target.type==='shelter'){state.health=Math.min(100,state.health+8);state.stamina=100;state.temp=36.6;state.wet=Math.max(0,state.wet-35);state.time=Math.min(20.5,state.time+1.4);toast('You rest by the cabin · recovered and warmed');save();return}collect(target.entity)}
function useSelected(){const it=state.inventory[selected];if(!it){toast('Nothing selected');return}if(it.id==='berries'){consume('berries');setMeter('food',state.food+22);toast('You eat the wild berries · nourishment restored')}else if(it.id==='water'){consume('water');setMeter('water',state.water+34);toast('You drink clean water · hydration restored')}else if(it.id==='bandage'){consume('bandage');setMeter('health',state.health+30);toast('Bandage applied · wounds dressed')}else if(it.id==='wood'){toast('Dry branches can be used to make a campfire (G)')}else if(it.id==='ammo'){toast('Cartridges · press R to reload')}else toast('This item cannot be used right now');renderInventory();save()}
