// Persist the complete field state, not just the map position.
const savePosition=save;
save=function(){state.x=player.x;state.z=player.z;state.yaw=player.yaw;state.pitch=player.pitch;state.found=pickups.filter(p=>p.taken).map(p=>`${p.type}:${p.x}:${p.z}`);state.ammo=Math.max(0,state.ammo);try{localStorage.setItem('wild-frontier-save',JSON.stringify(state))}catch{}};
