function begin(){if(started)return;started=true;$('#intro').classList.add('hidden');if(!mobile)canvas.requestPointerLock?.();toast('The Hushwood · find the supply cache near the cabin');updateHud()}
$('#beginButton').addEventListener('click',begin);
canvas.addEventListener('click',()=>{if(started&&paused&&!inventoryOpen&&!mobile)canvas.requestPointerLock?.();else if(started&&mobile)shoot()});
document.addEventListener('pointerlockchange',()=>{if(!mobile&&started&&!inventoryOpen){paused=document.pointerLockElement!==canvas;$('#pauseBadge').classList.toggle('show',paused);if(!paused)clockwork.getDelta()}});
document.addEventListener('mousemove',e=>{if(document.pointerLockElement===canvas&&!paused&&!inventoryOpen){player.yaw-=e.movementX*lookSensitivity;player.pitch=clamp(player.pitch-e.movementY*lookSensitivity,-1.35,1.35)}});
document.addEventListener('keydown',e=>{if(['Space','Tab','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.repeat)return;keys.add(e.code);if(e.code==='Escape'&&inventoryOpen){for(const id of ['#inventoryOverlay','#mapOverlay','#settingsOverlay'])$(id).classList.remove('open');inventoryOpen=false;return}if(e.code==='Tab'){toggleOverlay('#inventoryOverlay');return}if(e.code==='KeyM'){toggleOverlay('#mapOverlay');return}if(e.code==='Escape'&&paused){paused=false;$('#pauseBadge').classList.remove('show');canvas.requestPointerLock?.();return}if(!started||inventoryOpen)return;if(e.code==='KeyE')interact();if(e.code==='KeyR')reload();if(e.code==='KeyG')craftFire();if(e.code==='KeyF'){flashlightOn=!flashlightOn;flashlight.intensity=flashlightOn?2.5:0;toast(flashlightOn?'Flashlight on':'Flashlight off')}if(e.code==='KeyQ')useSelected();if(e.code==='KeyC')player.crouch=!player.crouch;if(e.code==='Digit1'||e.code==='Digit2'||e.code==='Digit3'||e.code==='Digit4'){selected=Number(e.code.slice(-1))-1;renderInventory()}if(e.code==='KeyT')toggleOverlay('#settingsOverlay')});
