const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome',args:['--no-sandbox','--disable-dev-shm-usage']});
 const page=await browser.newPage({viewport:{width:1050,height:793}});
 const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://127.0.0.1:3000/');await page.evaluate(()=>localStorage.setItem('wild-frontier-save',JSON.stringify({x:-4,z:7,yaw:0,pitch:-.025,found:[]})));await page.reload();await page.waitForTimeout(3000);
 await page.click('#beginButton');await page.waitForTimeout(500);
 let result={startCoords:await page.locator('#coords').innerText(),prompt:await page.locator('#promptText').innerText(),promptShown:await page.locator('#prompt').evaluate(e=>e.classList.contains('show'))};
 await page.keyboard.press('e');await page.waitForTimeout(300);
 result.collected={toast:await page.locator('#toastText').innerText(),save:await page.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save'))),prompt:await page.locator('#prompt').evaluate(e=>e.classList.contains('show'))};
 await page.keyboard.press('r');await page.waitForTimeout(300);result.reload={ammo:await page.locator('#ammo').innerText(),toast:await page.locator('#toastText').innerText()};
 await page.keyboard.down('w');await page.waitForTimeout(1500);await page.keyboard.up('w');await page.waitForTimeout(13000);
 result.movement={coords:await page.locator('#coords').innerText(),save:await page.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save')))};
 await page.reload();await page.waitForTimeout(3000);result.afterReload=await page.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save')));
 result.errors=errors;console.log(JSON.stringify(result,null,2));await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});

