const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
const exe='/home/runner/.cache/ms-playwright/chromium-1243/chrome-linux64/chrome';
async function makePage(browser,state,mobile=false){
 const context=await browser.newContext({viewport:mobile?{width:390,height:844}:{width:1050,height:793},isMobile:mobile,hasTouch:mobile,deviceScaleFactor:1});
 await context.addInitScript(s=>{if(!sessionStorage.getItem('wf-test-init')){localStorage.setItem('wild-frontier-save',JSON.stringify(s));sessionStorage.setItem('wf-test-init','1')}},state);
 const page=await context.newPage();const errors=[];page.on('pageerror',e=>errors.push(String(e)));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});
 await page.goto('http://127.0.0.1:3000/');await page.waitForTimeout(1400);return {context,page,errors};
}
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:exe,args:['--no-sandbox','--disable-dev-shm-usage']});
 const out={};
 // The crate gives 8 cartridges; reload consumes only enough to fill the magazine.
 {
  const t=await makePage(browser,{x:-2,z:-8,yaw:0,pitch:-.025,ammo:2});const p=t.page;await p.click('#beginButton');await p.keyboard.press('e');await p.waitForTimeout(250);
  out.cache={toast:await p.locator('#toastText').innerText(),ammoDisplay:await p.locator('#ammo').innerText(),save:await p.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save'))),errors:t.errors};
  await p.keyboard.press('r');await p.waitForTimeout(150);out.reload={display:await p.locator('#ammo').innerText(),toast:await p.locator('#toastText').innerText(),inventory:await p.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save')).inventory),errors:t.errors};
  await p.reload();await p.waitForTimeout(1000);out.cacheAfterReload={save:await p.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save'))),prompt:await p.locator('#prompt').evaluate(e=>e.classList.contains('show'))};await t.context.close();
 }
 // Face the nearby deer and fire once to verify an actual hit/state transition.
 {
  const t=await makePage(browser,{x:-8,z:-5,pitch:-.025,yaw:0,ammo:6});const p=t.page;await p.click('#beginButton');await p.locator('#world').click();await p.waitForTimeout(300);await p.mouse.down();await p.mouse.up();await p.waitForTimeout(250);
  out.combat={toast:await p.locator('#toastText').innerText(),ammo:await p.locator('#ammo').innerText(),save:await p.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save'))),errors:t.errors};await t.context.close();
 }
 // Coarse-pointer touch layout: look drag, joystick movement, shooting and contextual pickup.
 {
  const t=await makePage(browser,{x:-2,z:-8,yaw:0,pitch:-.025},true);const p=t.page;await p.click('#beginButton');await p.waitForTimeout(300);
  const controls=await p.evaluate(()=>({coarse:matchMedia('(pointer: coarse)').matches,display:getComputedStyle(document.querySelector('#mobileControls')).display,buttons:[...document.querySelectorAll('#mobileControls .touch-action')].map(b=>b.textContent)}));
  const start=await p.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save')));
  const j=await p.locator('#joystick').boundingBox();await p.mouse.move(j.x+j.width/2,j.y+j.height/2);await p.mouse.down();await p.mouse.move(j.x+j.width/2,j.y+j.height/2-45,{steps:5});await p.waitForTimeout(900);await p.mouse.up();await p.waitForTimeout(150);
  const moved=await p.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save')));
  const look=await p.locator('#touchLook').boundingBox();await p.mouse.move(look.x+look.width*.5,look.y+look.height*.55);await p.mouse.down();await p.mouse.move(look.x+look.width*.68,look.y+look.height*.55,{steps:5});await p.mouse.up();await p.waitForTimeout(100);
  const eBtn=p.locator('#mobileControls .touch-action').filter({hasText:'E'});await eBtn.dispatchEvent('pointerdown',{pointerId:1,pointerType:'touch',isPrimary:true});await p.waitForTimeout(200);
  out.mobile={controls,start:{x:start.x,z:start.z,yaw:start.yaw},afterMove:{x:moved.x,z:moved.z,yaw:moved.yaw},current:await p.evaluate(()=>JSON.parse(localStorage.getItem('wild-frontier-save'))),toast:await p.locator('#toastText').innerText(),errors:t.errors};await t.context.close();
 }
 await browser.close();console.log(JSON.stringify(out,null,2));
})().catch(e=>{console.error(e);process.exit(1)});

